### 💡 Intuition & Approach
Apply a legal stone placement or pass action to a Go board, resolve any resulting stone captures, and update player turns and terminal game states.

### ⚡ Python Reference Implementation
```python
import numpy as np

def alphago_l01_resolve_move(board: list, action: list, player: int, consecutive_passes: int = 0) -> dict:
    b = np.array(board, dtype=int).copy()
    H, W = b.shape
    opponent = 3 - player
    if action is None or len(action) == 0:
        new_passes = consecutive_passes + 1
        return {'board': b.tolist(), 'next_player': opponent, 'consecutive_passes': new_passes, 'captures': 0, 'is_terminal': new_passes >= 2}
    r, c = action[0], action[1]
    b[r, c] = player
    captures = 0
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < H and 0 <= nc < W and b[nr, nc] == opponent:
            v, q, grp, has_lib = set([(nr, nc)]), [(nr, nc)], [], False
            while q:
                curr_r, curr_c = q.pop(0)
                grp.append((curr_r, curr_c))
                for d1, d2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ar, ac = curr_r + d1, curr_c + d2
                    if 0 <= ar < H and 0 <= ac < W:
                        if b[ar, ac] == 0:
                            has_lib = True
                        elif b[ar, ac] == opponent and (ar, ac) not in v:
                            v.add((ar, ac))
                            q.append((ar, ac))
            if not has_lib:
                for gr, gc in grp:
                    if b[gr, gc] == opponent:
                        b[gr, gc] = 0
                        captures += 1
    return {'board': b.tolist(), 'next_player': opponent, 'consecutive_passes': 0, 'captures': captures, 'is_terminal': False}
```

### 📊 Complexity Analysis
- **Time Complexity:** $\mathcal{O}(N)$ where operations scale linearly with input dimensions.
- **Space Complexity:** $\mathcal{O}(N)$ for output buffers and intermediate tensors.

